INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3473, 'ចម្ការកៅស៊ូរាងការ៉េមួយព័ទ្ធខ្សែលួស \(3\) ជុំ អស់ខ្សែលួស \(864\ \text{m}\)។ ក. បរិមាត្រចម្ការ។ ខ. ជ្រុងចម្ការ។ គ. ផ្ទៃក្រឡាជាហិកតា។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(P = 864 \div 3 = 288\ \text{m}\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3474, 'សួនមួយរាងការ៉េមានជ្រុង \(7.9\ \text{dm}\) នៅលើផែនទីមាត្រដ្ឋាន \(\dfrac{1}{200}\)។ ក. ផ្ទៃក្រឡាលើផែនទី។ ខ. ជ្រុងពិតជាម៉ែត្រ។ គ. ផ្ទៃក្រឡាពិតជាម៉ែត្រការ៉េ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(\mathcal{A} = 7.9^2 = 62.41\ \text{dm}^2\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3475, 'សូផាតមើលផែនទីចម្ការកៅស៊ូរាងការ៉េ មាត្រដ្ឋាន \(\dfrac{1}{100\,000}\) ហើយបរិមាត្រលើផែនទី \(2.96\ \text{cm}\)។ គណនាជ្រុងពិត និងផ្ទៃក្រឡាពិតជាហិកតា។', NULL, '[]', 0, NULL, 5, 'writing', 'ជ្រុងលើផែនទី \(2.96 \div 4 = 0.74\ \text{cm}\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3476, 'ដីស្រែរាងត្រីកោណមានបាត \(120\ \text{m}\) កម្ពស់ \(80\ \text{m}\)។ គេជីកស្រះរាងចតុកោណ \(20 \times 10\ \text{m}\) ក្នុងស្រែ។ ក. ផ្ទៃក្រឡាស្រែ។ ខ. ផ្ទៃក្រឡាស្រះ។ គ. ផ្ទៃស្រែនៅសល់ជា a?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(\mathcal{A} = \dfrac{1}{2} \times 120 \times 80 = 4\,800\ \text{m}^2\) (2 ពិន្ទុ)
